/* Connected engineering tools and storage adapters. No credentials are held here. */
const studioBackend={enabled:false,request:null,flush:async()=>{},registerProject:()=>{},ai:false,sharing:false};
let studioTrash=studioStorage.json('studio-trash-v1',[],rows=>Array.isArray(rows)&&rows.every(r=>r&&StudioProjectData.validate(r.project)&&typeof r.project.id==='string'));
let localTrashVersion=studioStorage.read('studio-trash-v1');
let localStorageVersion=studioStorage.read('engineering-studio-v1'),localConflict=false,historyReplay=false,workspaceQuery='';
const editHistory=new Map();
function showSaveProblem(message){let notice=$('#studioSaveProblem');const parent=document.body.classList.contains('productMode')?$('.accountMain'):document.querySelector('.app main');if(!parent)return;if(!notice){parent.insertAdjacentHTML('afterbegin','<div id="studioSaveProblem" class="note saveProblem" role="alert"><b>Edits need attention</b><p></p><button type="button">Export current edits</button><span>Export before reloading to load the latest saved copy.</span></div>');notice=$('#studioSaveProblem');notice.querySelector('button').textContent=studioBackend.enabled?'Export current edits':'Export all current edits';notice.querySelector('button').onclick=()=>studioBackend.enabled?download(current.name+'-unsaved-edits.json',JSON.stringify(current,null,2),'application/json'):exportStudioBackup()}notice.querySelector('p').textContent=message}
function projectDesign(p=current){return p.designType||(/electronic/i.test(p.kind||'')&&!/electromechanical/i.test(p.kind||'')?'electronics':/enclosure/i.test(p.name||'')?'sketch':'slider-crank')}
projectSignature=function(p){return JSON.stringify({designType:projectDesign(p),stroke:p.stroke,rod:p.rod,rpm:p.rpm,material:p.material,parts:p.parts,sketch:p.sketch||[],circuit:p.circuit,resistorNetwork:p.resistorNetwork,costSettings:p.costSettings,electrical:p.electrical,currency:p.currency||'INR',assembly3d:p.assembly3d})};
function historyState(p=current){if(!editHistory.has(p.id))editHistory.set(p.id,{last:structuredClone(p),undo:[],redo:[]});return editHistory.get(p.id)}
function historyPayload(p){const copy=structuredClone(p);delete copy.version;return JSON.stringify(copy)}
function trackProjectChange(){const h=historyState();if(!historyReplay&&historyPayload(h.last)!==historyPayload(current)){h.undo.push(h.last);if(h.undo.length>50)h.undo.shift();h.redo=[]}h.last=structuredClone(current);if($('#undoEdit'))$('#undoEdit').disabled=!h.undo.length;if($('#redoEdit'))$('#redoEdit').disabled=!h.redo.length}
function undoStudio(redo=false){const h=historyState(),from=redo?h.redo:h.undo,to=redo?h.undo:h.redo;if(!from.length)return;to.push(structuredClone(current));const snapshot=from.pop(),id=current.id,version=current.version;Object.keys(current).forEach(k=>delete current[k]);Object.assign(current,snapshot,{id});if(version!==undefined)current.version=version;h.last=structuredClone(current);historyReplay=true;persist();historyReplay=false;render();toast(redo?'Edit redone':'Edit undone')}
const toolsLocalPersist=persist;
persist=function(){trackProjectChange();if(!projects.every(p=>StudioProjectData.validate(p))){showSaveProblem('An edit exceeds the project limits. Correct the value or export your edits.');return false}if(studioStorage.problems.has('engineering-studio-v1')){showSaveProblem('Saved project data needs recovery. Open Backups & recovery to export the original data.');return false}if(localConflict||studioStorage.read('engineering-studio-v1')!==localStorageVersion){localConflict=true;showSaveProblem('Another tab saved a newer version. Your edits remain here for export; saving is paused until you reload.');$('#saved').textContent='Conflict · export edits before reloading';toast('Another tab changed your projects. Export your edits, then reload.');return false}try{toolsLocalPersist();localStorageVersion=localStorage.getItem('engineering-studio-v1')}catch(e){$('#saved').textContent='Save failed · export a backup';showSaveProblem('Browser storage is unavailable. Export the current edits before reloading.');toast('Storage unavailable. Export this project to preserve your edits.');return false}};
window.addEventListener('storage',e=>{if(!studioBackend.enabled&&e.key==='engineering-studio-v1'&&e.newValue!==localStorageVersion){localConflict=true;showSaveProblem('Another tab changed the saved projects. Export your edits before reloading.');$('#saved').textContent='Another tab saved · export edits, then reload';toast('Projects changed in another tab. Reload before editing further.')}});
async function moveProjectToTrash(id){
 if(studioBackend.enabled){await studioBackend.flush();const p=projects.find(p=>p.id===id);await studioBackend.request('/projects/'+encodeURIComponent(id),'DELETE',{version:p.version});projects=projects.filter(p=>p.id!==id)}
 else{assertLocalProjectWrite();if(studioStorage.read('studio-trash-v1')!==localTrashVersion)throw Error('Trash changed in another tab. Reload before moving projects.');const p=projects.find(p=>p.id===id);if(!p)return;const next=[...studioTrash,{project:structuredClone(p),deletedAt:new Date().toISOString()}];localStorage.setItem('studio-trash-v1',JSON.stringify(next));const remaining=projects.filter(p=>p.id!==id);try{localStorage.setItem('engineering-studio-v1',JSON.stringify(remaining))}catch(e){throw Error('Could not finish moving the project. Its backup is in Trash.')}studioTrash=next;localTrashVersion=studioStorage.read('studio-trash-v1');projects=remaining;localStorageVersion=localStorage.getItem('engineering-studio-v1')}
 current=projects.find(p=>p.id===current?.id)||projects[0]||{...structuredClone(initial),id:'unsaved-empty',name:'Untitled project',parts:[],notes:[],revisions:[]};location.hash='/library';await showProductRoute();toast('Moved to Trash · restore it whenever you need it');
}
function requestTrash(id){const p=projects.find(p=>p.id===id);if(!p)return;modal('Move project to Trash?',`<p>${esc(p.name)} will leave your library. You can restore it from Trash. Existing share links will be revoked.</p>`,()=>{});const form=$('#modalForm');form.querySelector('button[type=submit]').textContent='Move to Trash';form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('button[type=submit]');b.disabled=true;try{await moveProjectToTrash(id);$('#dialog').close()}catch(err){toast(err.message)}finally{b.disabled=false}}}
async function trashDialog(){try{const rows=studioBackend.enabled?(await studioBackend.request('/projects?trash=true')).map(p=>({project:p})):studioTrash;modal('Project Trash',`<p class="tiny">Projects remain here until restored or their account/profile is deleted.</p><div>${rows.map((row,i)=>`<div class="listrow"><span>${esc(row.project.name)}</span><button type="button" data-restore-trash="${i}">Restore</button></div>`).join('')||'<p>Trash is empty.</p>'}</div>`,()=>{});$('#modalForm>button[type=submit]').style.display='none';document.querySelectorAll('[data-restore-trash]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const row=rows[+b.dataset.restoreTrash],p=row.project;if(studioBackend.enabled){const r=await studioBackend.request('/projects/'+encodeURIComponent(p.id)+'/restore','POST',{version:p.version});p.version=r.version;studioBackend.registerProject(p);projects.push(p)}else{assertLocalProjectWrite();if(studioStorage.read('studio-trash-v1')!==localTrashVersion)throw Error('Trash changed in another tab. Reload before restoring projects.');const restored={...structuredClone(p),id:projects.some(x=>x.id===p.id)?crypto.randomUUID():p.id};const remaining=studioTrash.filter(x=>x!==row);localStorage.setItem('engineering-studio-v1',JSON.stringify([...projects,restored]));projects.push(restored);localStorageVersion=localStorage.getItem('engineering-studio-v1');studioTrash=remaining;localStorage.setItem('studio-trash-v1',JSON.stringify(remaining));localTrashVersion=studioStorage.read('studio-trash-v1')}$('#dialog').close();showProductRoute();toast('Project restored')}catch(e){toast(e.message);b.disabled=false}})}catch(e){toast(e.message)}}
const toolsCard=studioProjectCard;studioProjectCard=function(p){return toolsCard(p).replace('</div></div></div></article>',`<button data-trash-project="${esc(p.id)}" aria-label="Move ${esc(p.name)} to Trash" title="Move to Trash">⌫</button></div></div></div></article>`)};
const toolsCardsBind=bindStudioCards;bindStudioCards=function(root=document){toolsCardsBind(root);root.querySelectorAll('[data-trash-project]').forEach(b=>b.onclick=()=>requestTrash(b.dataset.trashProject))};
const toolsLibrary=libraryPage;libraryPage=function(){return toolsLibrary().replace('<button id="dashboardImport">','<button type="button" data-show-trash>⌫ Trash</button><button id="dashboardImport">')};
const toolsDashboard=dashboardPage;dashboardPage=function(premium=false){return toolsDashboard(premium).replace('<button class="primary" data-create-project>','<button id="dashboardImport">↑ Import JSON</button><button class="primary" data-create-project>')};
const toolsProductBind=bindProduct;bindProduct=function(){toolsProductBind();document.querySelectorAll('[data-show-trash]').forEach(b=>b.onclick=trashDialog);bindThemeControls();};
const moneyFormats=['INR','USD','EUR','GBP','JPY'];
money=function(n){return new Intl.NumberFormat(undefined,{style:'currency',currency:moneyFormats.includes(current?.currency)?current.currency:'INR',maximumFractionDigits:2}).format(n)};
function seriesParallel(voltage,resistors,mode){if(!Array.isArray(resistors)||!Number.isFinite(voltage)||voltage<=0||voltage>100000||!resistors.length||resistors.length>20||resistors.some(r=>!Number.isFinite(r)||r<=0||r>1e12)||!['series','parallel'].includes(mode))throw Error('Use a positive voltage and 1–20 positive resistances.');const equivalent=mode==='series'?resistors.reduce((a,b)=>a+b,0):1/resistors.reduce((a,b)=>a+1/b,0),current=voltage/equivalent;if(!Number.isFinite(equivalent)||!Number.isFinite(current)||!Number.isFinite(voltage*current))throw Error('These values exceed the numerical range of this model.');return {equivalent,current,power:voltage*current,branches:resistors.map(r=>{const i=mode==='series'?current:voltage/r;return {resistance:r,voltage:i*r,current:i,power:i*(i*r)}})}}
function motionSample(stroke,rod,rpm,degrees){const k=kinematics(stroke,rod,degrees,rpm);if(!k.valid)throw Error('Rod length must exceed crank radius.');const r=stroke/2,t=degrees*Math.PI/180,c=Math.cos(t),s=Math.sin(t),d=Math.sqrt(rod*rod-r*r*s*s),w=rpm*2*Math.PI/60;return {...k,acceleration:(r*c+r*r*(c*c-s*s)/d+r**4*s*s*c*c/d**3)*w*w/1000}}
function motionSamples(start,end,step){if(![start,end,step].every(Number.isFinite)||start<0||end>360||end<=start||step<.25||step>90)throw Error('Use 0–360°, start < end, and a step from 0.25° to 90°.');const rows=[];for(let a=start;a<end;a+=step)rows.push({degrees:a,...motionSample(current.stroke,current.rod,current.rpm,a)});rows.push({degrees:end,...motionSample(current.stroke,current.rod,current.rpm,end)});return rows}
let motionStudy={start:0,end:360,step:3,quantity:'x'};
function motionPlot(rows,key){const values=rows.map(x=>x[key]),low=Math.min(0,...values),high=Math.max(...values),span=high-low||1,first=rows[0].degrees,range=rows.at(-1).degrees-first;const points=rows.map(r=>`${55+(r.degrees-first)/range*600},${175-(r[key]-low)/span*140}`);return `<svg class="plot" viewBox="0 0 700 215" role="img" aria-label="${{x:'Displacement',velocity:'Velocity',acceleration:'Acceleration'}[key]} over crank angle">${[0,.25,.5,.75,1].map(v=>`<path d="M55 ${175-v*140}H655" stroke="currentColor" opacity=".15"/><text x="3" y="${179-v*140}" fill="currentColor" font-size="10">${(low+v*span).toFixed(2)}</text>`).join('')}<polyline points="${points.join(' ')}" fill="none" stroke="var(--studio-accent)" stroke-width="2.5"/>${[0,.25,.5,.75,1].map(v=>`<text x="${50+v*600}" y="200" fill="currentColor" font-size="10">${(first+v*range).toFixed(0)}°</text>`).join('')}</svg>`}
function analysisTools(){return `<section class="card pageCard"><div class="sectionLead"><div><span class="eyebrow">IDEAL SLIDER-CRANK KINEMATICS</span><h2>Inspect every part of the cycle.</h2><p>Displacement, velocity and analytic acceleration at constant crank speed.</p></div><button id="motionCsv">↓ Export CSV</button></div><form id="motionStudyForm" class="motionControls"><div class="row">${field('motionStart','Start angle · °',motionStudy.start,'number')}${field('motionEnd','End angle · °',motionStudy.end,'number')}${field('motionStep','Sample step · °',motionStudy.step,'number')}<div class="field"><label for="motionQuantity">Plot</label><select id="motionQuantity">${[['x','Displacement · mm'],['velocity','Velocity · m/s'],['acceleration','Acceleration · m/s²']].map(([v,n])=>`<option value="${v}" ${v===motionStudy.quantity?'selected':''}>${n}</option>`).join('')}</select></div></div><button class="primary">Update study</button></form><div id="motionPlot"></div><p class="note">Rigid linkage at constant RPM. Loads, torque, friction, stress and fatigue require additional inputs and models.</p><button id="saveMotionEvidence">Record study in evidence</button></section>`}
function networkPanel(){const n=current.resistorNetwork||{mode:'series',voltage:12,resistors:[1000,2000]};return `<section class="card pageCard networkPanel"><div class="sectionLead"><div><span class="eyebrow">MULTI-COMPONENT CIRCUITS</span><h2>Series & parallel resistor network</h2><p>Calculate equivalent resistance and each resistor’s current, voltage and power.</p></div></div><form id="networkForm"><div class="row">${field('networkVoltage','Source voltage · V',n.voltage,'number')}<div class="field"><label for="networkMode">Topology</label><select id="networkMode"><option value="series" ${n.mode==='series'?'selected':''}>Series</option><option value="parallel" ${n.mode==='parallel'?'selected':''}>Parallel</option></select></div></div><div class="field"><label for="networkResistors">Resistors · Ω (comma separated, up to 20)</label><input id="networkResistors" value="${esc(n.resistors.join(', '))}" required></div><button class="primary">Calculate network</button></form><div id="networkResults"></div><p class="note">Ideal DC resistors. Wiring, component tolerance, AC behavior and thermal derating are outside this model.</p></section>`}
function renderNetwork(){try{const n=current.resistorNetwork||{mode:'series',voltage:12,resistors:[1000,2000]},r=seriesParallel(n.voltage,n.resistors,n.mode);$('#networkResults').innerHTML=`<div class="metrics">${metric('EQUIVALENT',r.equivalent.toFixed(2)+' Ω','Ideal resistance')}${metric('SOURCE CURRENT',(r.current*1000).toFixed(3)+' mA','Total current')}${metric('TOTAL POWER',r.power.toFixed(5)+' W','Sum of dissipated power')}</div><div class="tableWrap"><table><thead><tr><th>Resistor</th><th>Resistance · Ω</th><th>Voltage · V</th><th>Current · mA</th><th>Power · W</th></tr></thead><tbody>${r.branches.map((b,i)=>`<tr><td>R${i+1}</td><td>${b.resistance}</td><td>${b.voltage.toFixed(3)}</td><td>${(b.current*1000).toFixed(3)}</td><td>${b.power.toFixed(5)}</td></tr>`).join('')}</tbody></table></div>`}catch(e){$('#networkResults').textContent=e.message}}
const originalDesignV2=designV2;designV2=function(){const kind=projectDesign();if(kind==='electronics')return `<div class="sectionLead"><div><span class="eyebrow">ELECTRONICS PROJECT</span><h2>Your circuit, connected.</h2><p>The design view follows your project type. Start with the network, then document components and evidence.</p></div><button data-tab="electronics">Open electronics →</button></div>${networkPanel()}${engineeringGuidePanel()}`;if(kind==='sketch')return `<div class="sectionLead"><div><span class="eyebrow">SKETCH PROJECT</span><h2>Give the concept a shape.</h2><p>Edit dimensions, annotations and layers in Sketch. Document the assembly and fabrication assumptions as you go.</p></div><button data-tab="sketch">Edit concept sketch →</button></div><section class="card sketchPreview"><svg viewBox="0 0 800 440" role="img" aria-label="Project concept sketch">${sketchMarkup()}</svg></section>${engineeringGuidePanel()}`;return originalDesignV2()};
function engineeringGuidePanel(){return `<section class="card pageCard assistant"><h2>Engineering guide</h2><div class="assistantBody"><p id="answer">Ask about the concept, assumptions, or next steps.</p><form id="guide"><div class="promptrow"><input id="question" aria-label="Ask engineering guide" placeholder="Ask about this project…" required><button class="primary" aria-label="Send question">↗</button></div></form></div></section>`}
const localEngineeringGuide=guide;guide=function(q){if(studioBackend.enabled&&$('#liveAiChoice')?.checked)return runLiveGuide(q);if(projectDesign()==='slider-crank')return localEngineeringGuide(q);$('#answer').textContent=/cost|price/i.test(q)?`Component planning estimate: ${money(total())}. Use quoted prices and record supplier assumptions.`:projectDesign()==='electronics'?'Use Electronics to compare series and parallel resistors, inspect ideal current and power, and document the electrical specification. Real component ratings and tolerances need separate verification.':'Use Sketch to select, move and resize concept shapes, add labels and dimensions, and organize layers. This sketch does not certify fabrication readiness.'};
async function runLiveGuide(q){const answer=$('#answer'),buttons=document.querySelectorAll('#guide button,[data-question]');buttons.forEach(b=>b.disabled=true);answer.textContent='Requesting an AI explanation…';try{const r=await studioBackend.request('/projects/'+encodeURIComponent(current.id)+'/guide','POST',{question:q,include_context:!!$('#aiIncludeContext')?.checked});answer.textContent=r.answer;answer.insertAdjacentHTML('beforeend',`<small class="aiAttribution">AI-generated · ${esc(r.model)} · Verify calculations and assumptions independently.</small>`)}catch(e){answer.textContent=e.message}finally{buttons.forEach(b=>b.disabled=false)}}
function guideOptions(){if(!$('#guide'))return;$('#guide').insertAdjacentHTML('afterend',`<div class="guideOptions">${studioBackend.enabled&&studioBackend.ai?'<label><input id="liveAiChoice" type="checkbox"> Use live AI (sends this question to OpenAI)</label><label><input id="aiIncludeContext" type="checkbox"> Include dimensions/material and circuit parameters</label>':'<span>Local guidance · live AI requires a configured server.</span>'}</div>`)}
function designSettings(){modal('Project settings',field('projectRename','Project name',current.name)+`<div class="field"><label for="designType">Design model</label><select id="designType" name="designType">${[['slider-crank','Slider-crank mechanism'],['electronics','Electronics'],['sketch','Concept sketch']].map(([v,n])=>`<option value="${v}" ${projectDesign()===v?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label for="projectCurrency">Planning currency</label><select id="projectCurrency" name="projectCurrency">${moneyFormats.map(v=>`<option ${v===(current.currency||'INR')?'selected':''}>${v}</option>`).join('')}</select></div><p class="note">Changing currency relabels entered amounts. It does not convert exchange rates. Review component prices after switching.</p>`,f=>{const name=f.get('projectRename').trim();if(!name)return;current.name=name.slice(0,200);current.designType=f.get('designType');current.currency=f.get('projectCurrency');persist();render();toast('Project settings updated')});$('#projectRename').required=true;$('#projectRename').maxLength=200}
const toolsTemplate=buildStudioTemplate;buildStudioTemplate=function(id,name){const p=toolsTemplate(id,name);p.designType=id==='dc'?'electronics':['enclosure','drone','solid'].includes(id)?'sketch':'slider-crank';p.currency='INR';return p};
newProject=function(){modal('Create an engineering project',field('newConceptName','Project name','')+'<div class="field"><label for="newDesignType">Design model</label><select id="newDesignType"><option value="slider-crank">Slider-crank mechanism</option><option value="electronics">Electronics</option><option value="sketch">Concept sketch</option></select></div>',()=>{});$('#newConceptName').required=true;$('#newConceptName').maxLength=200;$('#modalForm>button[type=submit]').textContent='Create project';$('#modalForm').onsubmit=async e=>{e.preventDefault();const name=$('#newConceptName').value.trim();if(!name)return;const b=e.target.querySelector('button[type=submit]');b.disabled=true;try{const designType=$('#newDesignType').value,kind={electronics:'Electronics project',sketch:'Concept sketch','slider-crank':'Mechanical assembly'}[designType];await saveNewStudioProject({...structuredClone(initial),name,kind,designType,currency:'INR',parts:[],notes:[],revisions:[]});$('#dialog').close();if(location.hash.startsWith('#/workspace')){page='design';render()}else location.hash='/workspace';toast('Project created')}catch(e){toast(e.message)}finally{b.disabled=false}}};
function workspaceProjectSearch(){if(!$('#railProjectSearch')){$('#projectNav').insertAdjacentHTML('beforebegin','<label class="railProjectSearch"><span class="srOnly">Search workspace projects</span><input id="railProjectSearch" aria-label="Search workspace projects" placeholder="Find a project…"></label>')}const input=$('#railProjectSearch');input.value=workspaceQuery;input.oninput=e=>{workspaceQuery=e.target.value;filterWorkspaceProjects()};filterWorkspaceProjects()}
function filterWorkspaceProjects(){document.querySelectorAll('#projectNav [data-project]').forEach(el=>el.hidden=!el.textContent.toLowerCase().includes(workspaceQuery.toLowerCase()))}
function tabAccessibility(){const tabsRoot=$('#tabs');tabsRoot.setAttribute('role','tablist');tabsRoot.setAttribute('aria-label','Project tools');$('#content').setAttribute('role','tabpanel');$('#content').id='content';document.querySelectorAll('#tabs [data-tab]').forEach(b=>{b.setAttribute('role','tab');b.id='tool-tab-'+b.dataset.tab;b.setAttribute('aria-controls','content');b.setAttribute('aria-selected',String(page===b.dataset.tab));b.tabIndex=page===b.dataset.tab?0:-1;b.onkeydown=e=>{const buttons=[...document.querySelectorAll('#tabs [data-tab]')],index=buttons.indexOf(b);let next;if(e.key==='ArrowRight')next=(index+1)%buttons.length;if(e.key==='ArrowLeft')next=(index+buttons.length-1)%buttons.length;if(e.key==='Home')next=0;if(e.key==='End')next=buttons.length-1;if(next!==undefined){e.preventDefault();page=buttons[next].dataset.tab;render();$('#tool-tab-'+page).focus()}}});if($('#tool-tab-'+page))$('#content').setAttribute('aria-labelledby','tool-tab-'+page)}
let notificationTimer=0;
async function notificationInbox(){if(!studioBackend.enabled){modal('Notifications','<p>Account notifications are available when the server is connected.</p>',()=>{});return}try{const rows=await studioBackend.request('/notifications');modal('Notifications',rows.map(n=>`<div class="listrow"><span>${esc(n.message)}</span>${n.read?'<small>Read</small>':`<button type="button" data-read-inbox="${esc(n.id)}">Mark read</button>`}</div>`).join('')||'<p>You’re all caught up.</p>',()=>{});$('#modalForm>button[type=submit]').style.display='none';document.querySelectorAll('[data-read-inbox]').forEach(b=>b.onclick=async()=>{try{await studioBackend.request('/notifications/'+encodeURIComponent(b.dataset.readInbox)+'/read','POST',{});b.outerHTML='<small>Read</small>';refreshNotificationCount()}catch(e){toast(e.message)}})}catch(e){toast(e.message)}}
async function refreshNotificationCount(){if(!studioBackend.enabled||document.hidden||!$('#workspaceInbox'))return;try{const rows=await studioBackend.request('/notifications');const el=$('#workspaceInbox');if(el){const count=rows.filter(n=>!n.read).length;el.textContent='♧ '+(count||'');el.setAttribute('aria-label',`Notifications, ${count} unread`)}}catch{}}
async function shareProject(){if(!studioBackend.enabled||!studioBackend.sharing){modal('Share a project','<p>Expiring read-only links require the backend and SHARING_ENABLED=true. You can export a JSON copy from this preview.</p>',()=>{});return}try{await studioBackend.flush();const rows=await studioBackend.request('/projects/'+encodeURIComponent(current.id)+'/shares');modal('Read-only project snapshots',`<p>A link includes this project’s notes, specification, sketch and components. Anyone holding the link can read its snapshot until expiry. Later edits do not change the snapshot.</p><div class="field"><label for="shareDays">Expires in days (1–30)</label><input id="shareDays" type="number" min="1" max="30" value="7" required></div><div id="shareResult"></div>${rows.filter(x=>!x.revoked).map(x=>`<div class="listrow"><span>Expires ${esc(new Date(x.expires*1000).toLocaleDateString())}</span><button type="button" data-revoke-share="${esc(x.id)}">Revoke link</button></div>`).join('')}`,()=>{});$('#modalForm>button[type=submit]').textContent='Create expiring link';$('#modalForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button[type=submit]');b.disabled=true;try{const r=await studioBackend.request('/projects/'+encodeURIComponent(current.id)+'/shares','POST',{version:current.version,days:+$('#shareDays').value});$('#shareResult').innerHTML=`<label for="shareUrl">Copy this link (shown only now)</label><input id="shareUrl" readonly value="${esc(r.url)}"><p class="tiny">Snapshot expires ${esc(new Date(r.expires*1000).toLocaleString())}</p>`}catch(e){toast(e.message)}finally{b.disabled=false}};document.querySelectorAll('[data-revoke-share]').forEach(b=>b.onclick=async()=>{try{await studioBackend.request('/projects/'+encodeURIComponent(current.id)+'/shares/'+encodeURIComponent(b.dataset.revokeShare),'DELETE');b.textContent='Revoked';b.disabled=true}catch(e){toast(e.message)}})}catch(e){toast(e.message)}}
