 canvas.onpointerdown=e=>{const start=point(e);if(sketchTool==='select'){const index=Number(e.target.closest('[data-shape-index]')?.dataset.shapeIndex);sketchSelection=Number.isInteger(index)&&current.sketch?.[index]?index:-1;sketchDrag={start,original:sketchSelection>=0?structuredClone(current.sketch[sketchSelection]):null};}else if(sketchTool==='text'){current.sketch||=[];current.sketch.push({type:'text',...start,text:$('#newSketchText').value.slice(0,200)||'Label',layer:activeSketchLayer});sketchSelection=current.sketch.length-1;persist();render();return}else sketchDrag={start};canvas.setPointerCapture(e.pointerId)};
 canvas.onpointermove=e=>{const p=point(e);$('#sketchStatus').textContent=`X ${p.x} · Y ${p.y} mm`;if(!sketchDrag)return;if(sketchTool==='select'&&sketchDrag.original){const s=structuredClone(sketchDrag.original),dx=p.x-sketchDrag.start.x,dy=p.y-sketchDrag.start.y;s.x+=dx;s.y+=dy;if(s.x2!==undefined){s.x2+=dx;s.y2+=dy}current.sketch[sketchSelection]=s;$('#shapes').innerHTML=sketchMarkup()}else if(sketchTool!=='select')$('#draftShape').innerHTML=sketchShapesMarkup([shape(sketchDrag.start,p)])};
 canvas.onpointerup=e=>{if(!sketchDrag)return;const p=point(e);if(sketchTool==='select'){if(sketchDrag.original)persist()}else if(Math.hypot(p.x-sketchDrag.start.x,p.y-sketchDrag.start.y)>2){current.sketch||=[];current.sketch.push({...shape(sketchDrag.start,p),layer:activeSketchLayer});sketchSelection=current.sketch.length-1;persist()}sketchDrag=null;render()};
