 if($('#shapeProperties')){const s=current.sketch[sketchSelection];Object.keys(s).filter(k=>!['type','text','layer'].includes(k)).forEach(k=>{const el=$('#shape_'+k);if(el){el.min=['w','h','r'].includes(k)?'0':'-10000';el.max=10000;el.step='any'}});$('#shapeProperties').onsubmit=e=>{e.preventDefault();const copy=structuredClone(s);for(const k of Object.keys(s).filter(k=>!['type','text','layer'].includes(k))){copy[k]=+$('#shape_'+k).value;if(!Number.isFinite(copy[k])||Math.abs(copy[k])>10000)return toast('Use finite dimensions between −10000 and 10000 mm.')}if($('#shape_text'))copy.text=$('#shape_text').value.slice(0,200);copy.layer=$('#shape_layer').value.trim().slice(0,50)||'Concept';current.sketch[sketchSelection]=copy;persist();render()};$('#deleteShape').onclick=()=>{current.sketch.splice(sketchSelection,1);sketchSelection=-1;persist();render()}}
