const toolsCompare=compare;compare=function(index){if(projectDesign()==='slider-crank'&&(current.revisions[index].snapshot.currency||'INR')===(current.currency||'INR'))return toolsCompare(index);const p=current.revisions[index].snapshot,values=[['Design model',projectDesign(p),projectDesign()],['Currency',p.currency||'INR',current.currency||'INR'],['Component estimate',p.parts.reduce((n,x)=>n+x.qty*x.price,0).toFixed(2)+' '+(p.currency||'INR'),total().toFixed(2)+' '+(current.currency||'INR')],['Components',p.parts.length,current.parts.length],['Sketch objects',(p.sketch||[]).length,(current.sketch||[]).length],['Evidence notes',p.notes.length,current.notes.length],['Electrical specification',p.electrical||'Not specified',current.electrical||'Not specified'],['Resistor network',JSON.stringify(p.resistorNetwork||{}),JSON.stringify(current.resistorNetwork||{})]];$('#comparison').innerHTML=`<div class="tableWrap"><table><thead><tr><th>Property</th><th>Snapshot</th><th>Current</th><th>Status</th></tr></thead><tbody>${values.map(([label,a,b])=>`<tr><td>${label}</td><td>${esc(a)}</td><td>${esc(b)}</td><td>${a===b?'Unchanged':'Modified'}</td></tr>`).join('')}</tbody></table></div>`};

studioGuides[0][1]='Choose a slider-crank, electronics or concept-sketch design model in Project settings. Motion studies support a slider-crank at constant RPM, including displacement, velocity and acceleration. Force, stress, fatigue and motor sizing require further models.';
studioGuides[1][1]='Draw rectangles, circles, lines, labels and measured dimension annotations. Select and move objects or edit their dimensions and layers in the inspector. Export SVG or DXF, and use session undo/redo. Annotations measure geometry; they are not constraints or manufacturing validation.';
studioGuides[3][1]='Inspect a single DC resistor or a series/parallel network of up to 20 resistors. Compare equivalent resistance and each component’s voltage, current and power. AC behavior, tolerances, heat and protection require separate verification.';
studioGuides[5][1]='Export a project as JSON for re-import, motion to CSV, sketches to SVG/DXF, and the report to HTML. Trash keeps deleted projects recoverable. Browser-local projects and Trash remain on this device. On a save conflict, export your edits before reloading.';

const toolsNavigate=navigate;navigate=function(target){if(target==='projects'){location.hash='/library';return}toolsNavigate(target)};
